h:900px){.api-search{grid-template-columns:1fr}.api-results{grid-template-columns:1fr}.api-sidebar{max-height:none}.api-shell{display:block}.api-sidebar{display:flex!important;position:static!important;flex-wrap:wrap;gap:8px;padding:12px;margin-bottom:24px;border-bottom:1px solid #dce9f0}.api-sidebar .sidebar-group,.api-sidebar .sidebar-group~a:not(.active){display:none}.api-sidebar .api-back{margin:0}.api-sidebar>a{width:auto}.api-content{padding:0!important}}
